type Tree = { value: number; left: Tree | null; right: Tree | null };
function readTree(values: (number | null)[]): Tree | null {
  if (values.length === 0 || values[0] === null) return null;
  const root: Tree = { value: values[0], left: null, right: null };
  const queue: Tree[] = [root]; let index = 1;
  for (let i = 0; i < queue.length && index < values.length; i++) {
    const node = queue[i];
    for (const side of ['left', 'right'] as const) {
      const value = values[index++];
      if (value !== null && value !== undefined) { const child: Tree = { value, left: null, right: null }; node[side] = child; queue.push(child); }
    }
  }
  return root;
}
export function isSymmetric(values: (number | null)[]): boolean {
  function mirror(a: Tree | null, b: Tree | null): boolean { if (!a || !b) return a === b; return a.value === b.value && mirror(a.left,b.right) && mirror(a.right,b.left); } const root = readTree(values); return !root || mirror(root.left,root.right);
}
